const ICON_KEG = '<svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="3" width="12" height="18" rx="3"></rect><path d="M6 8h12"></path><path d="M6 16h12"></path></svg>';

function stripEmoji(t) { return String(t).replace(/^[^\p{L}\p{N}+]+/u, '').trim(); }

// Rearranges the rendered cards into the redesigned layout: header row, chart +
// fermentation column, settings in tabs. Only moves existing nodes, so every id,
// inline handler and listener keeps working.
function enhanceCards(valid) {
  const content = document.getElementById('content');
  const mk = (tag, cls) => { const n = document.createElement(tag); n.className = cls; return n; };

  const boxes = [...content.querySelectorAll(':scope > .link-box-top')];
  boxes.forEach(b => { const l = b.querySelector('.link-box-label'); if (l) l.textContent = stripEmoji(l.textContent); });
  if (boxes.length > 1) {
    const extras = mk('details', 'extras');
    extras.innerHTML = '<summary>TV / embed view and iPhone widget</summary>';
    boxes[0].after(extras);
    boxes.slice(1).forEach(b => extras.appendChild(b));
  }

  content.querySelectorAll(':scope > .card').forEach((card, cardIdx) => {
    const canvas = card.querySelector('canvas');
    const ring = card.querySelector(':scope > .ring-wrap');
    if (!canvas && !ring) { card.classList.add('card-add'); return; }

    const head = mk('div', 'card-head');
    const name = card.querySelector(':scope > .device-name, :scope > .keg-title');
    const pill = card.querySelector(':scope > .status-pill');
    const wifi = card.querySelector(':scope > .wifi-badge');
    const icon = mk('span', 'card-icon');
    icon.innerHTML = canvas ? ICON_AIRLOCK : ICON_KEG;
    head.appendChild(icon);
    if (name) {
      if (name.firstChild && name.firstChild.nodeType === 3) name.firstChild.nodeValue = stripEmoji(name.firstChild.nodeValue) + ' ';
      const titleWrap = mk('div', 'card-title-wrap');
      titleWrap.appendChild(name);
      if (canvas) { const seen = mk('div', 'last-seen'); seen.id = `lastSeen-${cardIdx}`; titleWrap.appendChild(seen); }
      head.appendChild(titleWrap);
    }
    const meta = mk('div', 'card-meta');
    if (pill) meta.appendChild(pill);
    if (wifi) meta.appendChild(wifi);
    head.appendChild(meta);
    card.prepend(head);

    const blocks = [...card.querySelectorAll(':scope > .integration-block')];

    if (canvas) {
      const grid = mk('div', 'al-grid'), main = mk('div', 'al-main'), side = mk('div', 'al-side'), box = mk('div', 'chart-box');
      const stats = card.querySelector(':scope > .stats');
      const ranges = card.querySelector(':scope > .ranges');
      const exportLine = canvas.nextElementSibling;
      head.after(grid);
      grid.append(main, side);
      if (stats) main.appendChild(stats);
      if (ranges) main.appendChild(ranges);
      main.appendChild(box);
      box.appendChild(canvas);
      if (exportLine && exportLine.tagName === 'P') main.appendChild(exportLine);

      const hist = blocks.find(b => b.querySelector('[id^="historyList-"]'));
      if (hist) {
        blocks.splice(blocks.indexOf(hist), 1);
        hist.classList.add('ferment-block');
        hist.style.marginTop = '';
        side.appendChild(hist);
        const lab = hist.querySelector(':scope > label.check-row');
        if (lab) {
          lab.textContent = 'Fermentation';
          const info = (valid && valid[cardIdx] && valid[cardIdx].info) || {};
          const started = parseInt(info.fermentation_started_at, 10) || 0;
          const count = parseInt(info.fermentation_bubble_count != null ? info.fermentation_bubble_count : info.total_bubble_count, 10);
          const parts = [];
          if (started) {
            parts.push('Started ' + new Date(started * 1000).toLocaleDateString());
            parts.push('day ' + (Math.floor((Date.now() / 1000 - started) / 86400) + 1));
          }
          if (!isNaN(count)) parts.push(count.toLocaleString() + (started ? ' bubbles' : ' bubbles counted so far'));
          if (parts.length) { const sum = mk('p', 'ferment-summary'); sum.textContent = parts.join(' · '); lab.after(sum); }
        }
        const start = hist.querySelector('button[onclick^="startNewFermentation"]');
        const arch = hist.querySelector('button[onclick^="archiveBatch"]');
        if (start && arch) { start.classList.add('primary'); start.style.marginTop = ''; arch.before(start); }
      }
    } else {
      const grid = mk('div', 'keg-grid'), right = mk('div', 'keg-right');
      head.after(grid);
      grid.append(ring, right);
      card.querySelectorAll(':scope > .cal-notice, :scope > .stats').forEach(n => right.appendChild(n));
    }

    if (!blocks.length) return;
    const tabs = mk('div', 'tabs'), panels = mk('div', 'tab-panels');
    tabs.setAttribute('role', 'tablist');
    const short = { 'Rename this device': 'Name', 'Send to Grainfather': 'Grainfather', 'Send to Brewfather': 'Brewfather' };
    const activate = (i) => {
      [...tabs.children].forEach((t, j) => { t.classList.toggle('active', j === i); t.setAttribute('aria-selected', j === i ? 'true' : 'false'); });
      blocks.forEach((b, j) => { b.hidden = j !== i; });
    };
    let first = 0;
    blocks.forEach((b, i) => {
      const lab = b.querySelector(':scope > label.check-row, :scope > summary');
      let title = lab ? stripEmoji(lab.textContent) : 'Settings';
      title = short[title] || title;
      if (title === 'Brew details') first = i;
      const tab = mk('button', 'tab');
      tab.type = 'button';
      tab.setAttribute('role', 'tab');
      tab.textContent = title;
      tab.addEventListener('click', () => activate(i));
      tabs.appendChild(tab);
      b.classList.add('tab-panel');
      b.style.marginTop = '';
      if (b.tagName === 'DETAILS') b.open = true;
      panels.appendChild(b);
    });
    activate(first);
    const note = card.querySelector(':scope > .keg-note');
    card.append(tabs, panels);
    labelFields(panels);
    if (note) card.appendChild(note);
    card.querySelectorAll('.cal-notice a').forEach(a => a.addEventListener('click', () => {
      const target = card.querySelector('[id^="calibrate-"]');
      const i = blocks.indexOf(target);
      if (i >= 0) { activate(i); target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    }));
  });

  new MutationObserver(muts => {
    for (const m of muts) {
      const node = m.target.nodeType === 3 ? m.target.parentElement : m.target;
      if (!node || !node.classList || !node.classList.contains('save-status')) continue;
      const text = node.textContent.trim();
      if (text && !/(\.\.\.|…)$/.test(text)) showToast(text);
    }
  }).observe(content, { childList: true, subtree: true, characterData: true });
}

// Puts a visible caption above every settings field (they used to rely on placeholders only).
function labelFields(root) {
  const selectLabels = { gfUnit: 'Temperature unit', gfMode: 'Gravity source', bfUnit: 'Temperature unit' };
  root.querySelectorAll('input[type="text"]:not([readonly]), select').forEach(inp => {
    if (inp.closest('label')) return;
    let text = '';
    let ph = inp.getAttribute('placeholder') || '';
    if (inp.tagName === 'SELECT') {
      text = selectLabels[(inp.id || '').split('-')[0]] || '';
    } else if (!/^e\.g\./i.test(ph)) {
      const optional = /^optional:\s*/i.test(ph);
      ph = ph.replace(/^optional:\s*/i, '');
      const m = ph.match(/^(.*?)\s*\((.*)\)\s*$/);
      if (m) { text = m[1]; if (/^optional$/i.test(m[2])) { text += ' (optional)'; ph = ''; } else { ph = m[2]; } }
      else { text = ph; ph = ''; }
      if (optional) text += ' (optional)';
    }
    if (!text) return;
    const field = document.createElement('label');
    field.className = 'field';
    const cap = document.createElement('span');
    cap.textContent = text.charAt(0).toUpperCase() + text.slice(1);
    inp.before(field);
    field.append(cap, inp);
    if (inp.tagName !== 'SELECT') inp.setAttribute('placeholder', ph);
    inp.style.marginTop = '';
  });
  [['alStyle', 'alDate'], ['alOg', 'alFg'], ['beerStyle', 'kegDate'], ['ogInput', 'fgInput'], ['tempMin', 'tempMax'], ['gfOg', 'gfVol'], ['bfOg', 'bfBatchVolume']].forEach(([a, b]) => {
    root.querySelectorAll(`[id^="${a}-"]`).forEach(x => {
      const y = document.getElementById(b + '-' + x.id.split('-')[1]);
      const fa = x.closest('label.field');
      const fb = y && y.closest('label.field');
      if (fa && fb && fa.nextElementSibling === fb) { const row = document.createElement('div'); row.className = 'field-row'; fa.before(row); row.append(fa, fb); }
    });
  });
}

function showToast(text) {
  let t = document.getElementById('toast');
  if (!t) { t = document.createElement('div'); t.id = 'toast'; t.setAttribute('role', 'status'); document.body.appendChild(t); }
  t.textContent = text;
  t.className = /fail|must|error|invalid|can't/i.test(text) ? 'show bad' : 'show';
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => { t.className = ''; }, 3200);
}

function agoText(minutes) {
  if (minutes < 1.5) return 'just now';
  if (minutes < 60) return Math.round(minutes) + ' min ago';
  if (minutes < 1440) return Math.round(minutes / 60) + ' h ago';
  return Math.round(minutes / 1440) + ' d ago';
}

function chartColors() {
  const cs = getComputedStyle(document.documentElement);
  const v = n => cs.getPropertyValue(n).trim();
  return { temp: v('--cream'), bubbles: v('--amber'), grid: v('--hairline'), tick: v('--cream-dim'), panel: v('--panel-raised') };
}

function applyChartColors(chart) {
  const c = chartColors();
  const [t, b] = chart.data.datasets;
  t.borderColor = c.temp;
  b.borderColor = c.bubbles;
  b.backgroundColor = c.bubbles + '22';
  const sc = chart.options.scales;
  sc.x.ticks.color = c.tick; sc.x.grid.color = c.grid;
  sc.y.ticks.color = c.temp; sc.y.grid.color = c.grid;
  sc.y1.ticks.color = c.bubbles;
  chart.options.plugins.legend.labels.color = c.temp;
  const tip = chart.options.plugins.tooltip;
  tip.backgroundColor = c.panel; tip.borderColor = c.grid; tip.titleColor = c.temp; tip.bodyColor = c.temp;
}

function restyleCharts() {
  Object.values(charts).forEach(ch => { if (ch) { applyChartColors(ch); ch.update('none'); } });
}

